import express, { type ErrorRequestHandler } from 'express';
import { z } from 'zod';
import { createLogger } from './index-core';
import { createPrototypeHostRouter } from './routes/prototypeHost';
import { DiskBundleStore, ensureBundleRoot } from './services/BundleStore';
import { SupabaseAuthService } from './services/SupabaseAuthService';
import { DEFAULT_PROTOTYPE_HOST_URL } from './config/proxy';
import { enableHostedLogPrivacy } from './utils/hostedLogging';

enableHostedLogPrivacy();
const log = createLogger('PrototypeHostBootstrap');

const envSchema = z.object({
  PORT: z.coerce.number().int().positive().default(4100),
  PROTOTYPE_HOST_PUBLIC_URL: z
    .string()
    .min(1)
    .default(DEFAULT_PROTOTYPE_HOST_URL),
  PROTOTYPE_BUNDLE_ROOT: z
    .string()
    .min(1)
    .default('/var/rivet-prototype-bundles'),
  PROTOTYPE_MAX_BUNDLE_MB: z.coerce.number().int().positive().default(25),
  SUPABASE_URL: z.string().min(1),
  SUPABASE_ANON_KEY: z.string().min(1),
});

const MALFORMED_REQUEST_STATUS = 400;
const OVERSIZED_REQUEST_STATUS = 413;
const UNSUPPORTED_ENCODING_STATUS = 415;
const REQUEST_FAILURE_STATUS = 500;
const handleRequestError: ErrorRequestHandler = (
  error: unknown,
  _req,
  res,
  _next,
) => {
  log.warn('Prototype request failed', error);
  if (res.headersSent) {
    res.destroy();
    return;
  }
  const errorType =
    error && typeof error === 'object' && 'type' in error
      ? error.type
      : undefined;
  if (errorType === 'entity.parse.failed') {
    res
      .status(MALFORMED_REQUEST_STATUS)
      .json({ error: 'Invalid request body' });
    return;
  }
  if (errorType === 'entity.too.large') {
    res
      .status(OVERSIZED_REQUEST_STATUS)
      .json({ error: 'Request body too large' });
    return;
  }
  if (errorType === 'encoding.unsupported') {
    res
      .status(UNSUPPORTED_ENCODING_STATUS)
      .json({ error: 'Unsupported request body encoding' });
    return;
  }
  res.status(REQUEST_FAILURE_STATUS).json({ error: 'Request failed' });
};

const main = async (): Promise<void> => {
  const env = envSchema.parse(process.env);

  await ensureBundleRoot(env.PROTOTYPE_BUNDLE_ROOT);

  const app = express();
  app.use(express.json({ limit: `${env.PROTOTYPE_MAX_BUNDLE_MB + 5}mb` }));

  app.use(
    createPrototypeHostRouter({
      store: new DiskBundleStore(env.PROTOTYPE_BUNDLE_ROOT),
      auth: new SupabaseAuthService(),
      publicBaseUrl: env.PROTOTYPE_HOST_PUBLIC_URL,
      maxBundleBytes: env.PROTOTYPE_MAX_BUNDLE_MB * 1024 * 1024,
    }),
  );

  app.use(handleRequestError);

  app.listen(env.PORT, () => {
    log.info(
      `Prototype Preview Host listening on ${env.PORT} (bundles: ${env.PROTOTYPE_BUNDLE_ROOT})`,
    );
  });

  await new Promise(() => {});
};

void main().catch((error: unknown) => {
  log.error('Prototype host startup failed', error);
  process.exitCode = 1;
});
